@php
$news=\Illuminate\Support\Facades\DB::table('posts')->where('status','published')->whereNotNull('published_revision_id')->when(!empty($compact),fn($q)=>$q->limit(3))->when(request('categoria'),fn($q)=>$q->whereIn('id',\Illuminate\Support\Facades\DB::table('post_category_links')->join('post_categories','post_category_links.post_category_id','=','post_categories.id')->where('post_categories.slug',request('categoria'))->select('post_id')))->orderByDesc('published_at');
$news=empty($compact)?$news->paginate(12)->withQueryString():$news->get();
@endphp
<section class="shell section-space"><p class="eyebrow">NOVEDADES JMAC</p><h2>Actualidad de JMAC</h2>@if(empty($compact))<nav aria-label="Categorías de novedades">@foreach(\Illuminate\Support\Facades\DB::table('post_categories')->get() as $category)<a href="/novedades/?categoria={{ $category->slug }}">{{ $category->name }}</a> @endforeach</nav>@endif<div class="product-grid">@forelse($news as $post)<article class="product-card">@if($post->featured_media_id)<a href="/novedades/{{ $post->slug }}/"><img src="/media/{{ $post->featured_media_id }}" alt="{{ $post->title }}" loading="lazy" width="600" height="400"></a>@endif<div class="product-card-body"><p>{{ \Illuminate\Support\Carbon::parse($post->published_at)->format('d/m/Y') }}</p><h3><a href="/novedades/{{ $post->slug }}/">{{ $post->title }}</a></h3><p>{{ $post->excerpt }}</p><a href="/novedades/{{ $post->slug }}/">Leer novedad</a></div></article>@empty<div class="empty-state"><h3>Aún no hay publicaciones</h3><p>Las nuevas noticias de JMAC aparecerán aquí.</p></div>@endforelse</div>@if(empty($compact)){{ $news->links() }}@endif</section>
